// ─── File: GatewayPatternDemo.java ───
// Models the API Gateway pattern as an ordered chain of responsibility filters.
package com.bank.gateway.demo;

import java.util.*;
import java.util.logging.*;

public class GatewayPatternDemo {
    private static final Logger log = Logger.getLogger("GatewayPattern");
    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setLevel(Level.ALL); h.setFormatter(new GpLogFormatter());
        log.addHandler(h); log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        FilterChain chain = new FilterChain(List.of(
            new TracingFilter(),
            new AuthFilter(),
            new RateLimitFilter(3),
            new RoutingFilter()
        ));

        log.info("=== Valid request through full chain ===");
        RequestContext ok = new RequestContext("/api/v1/accounts/SAV2001", "rajesh", "valid-token");
        chain.run(ok);
        log.info(() -> "Response: " + ok.getResponse());

        log.info("=== Invalid token stopped by AuthFilter ===");
        RequestContext bad = new RequestContext("/api/v1/payments/pay", "priya", "bad-token");
        chain.run(bad);
        log.info(() -> "Response: " + bad.getResponse());
    }
}

// ─── Would be in core/RequestContext.java ───
class RequestContext {
    private final String path; private final String clientId; private final String token;
    private String correlationId; private String response; private boolean rejected;
    RequestContext(String path, String clientId, String token) {
            this.path = path;
            this.clientId = clientId
            this.token = token;
    }
    String getPath() { return path; }
    String getClientId() { return clientId; }
    String getToken() { return token; }
    String getCorrelationId() { return correlationId; }
    void setCorrelationId(String id) { this.correlationId = id; }
    String getResponse() { return response; }
    void setResponse(String r) { this.response = r; }
    boolean isRejected() { return rejected; }
        void reject(String reason) { this.rejected = true;
        this.response = reason; }
}

// ─── Would be in filter/GatewayFilter.java ───
interface GatewayFilter {
    // returns true to continue the chain, false to stop it.
    boolean apply(RequestContext ctx);
}

// ─── Would be in core/FilterChain.java ───
class FilterChain {
    private static final Logger log = Logger.getLogger("GatewayPattern");
    private final List<GatewayFilter> filters;
    FilterChain(List<GatewayFilter> filters) { this.filters = filters; }
    void run(RequestContext ctx) {
        for (GatewayFilter f : filters) {
            boolean cont = f.apply(ctx);
            if (!cont) {
                log.warning(() -> "Chain stopped at " + f.getClass().getSimpleName());
                return;
            }
        }
    }
}

// ─── Would be in filter/TracingFilter.java ───
class TracingFilter implements GatewayFilter {
    private static final Logger log = Logger.getLogger("GatewayPattern");
    public boolean apply(RequestContext ctx) {
        ctx.setCorrelationId(UUID.randomUUID().toString().substring(0, 8));
        log.info(() -> "[trace " + ctx.getCorrelationId() + "] " + ctx.getPath());
        return true;
    }
}

// ─── Would be in filter/AuthFilter.java ───
class AuthFilter implements GatewayFilter {
    private static final Logger log = Logger.getLogger("GatewayPattern");
    public boolean apply(RequestContext ctx) {
        if (!"valid-token".equals(ctx.getToken())) {
            ctx.reject("401 Unauthorized");
            log.warning(() -> "Auth failed client=" + ctx.getClientId());
            return false;
        }
        log.fine(() -> "Auth ok for " + ctx.getClientId());
        return true;
    }
}

// ─── Would be in filter/RateLimitFilter.java ───
class RateLimitFilter implements GatewayFilter {
    private static final Logger log = Logger.getLogger("GatewayPattern");
    private final Map<String, Integer> counts = new HashMap<>();
    private final int max;
    RateLimitFilter(int max) { this.max = max; }
    public boolean apply(RequestContext ctx) {
        int c = counts.merge(ctx.getClientId(), 1, Integer::sum);
            if (c > max) { ctx.reject("429 Too Many Requests");
            return false; }
        return true;
    }
}

// ─── Would be in filter/RoutingFilter.java ───
class RoutingFilter implements GatewayFilter {
    private static final Logger log = Logger.getLogger("GatewayPattern");
    public boolean apply(RequestContext ctx) {
        String service = ctx.getPath().startsWith("/api/v1/accounts") ? "account-service"
                       : ctx.getPath().startsWith("/api/v1/payments") ? "payment-service"
                       : "unknown";
            if (service.equals("unknown")) { ctx.reject("404 Not Found");
            return false; }
        ctx.setResponse("200 OK from " + service + " [trace " + ctx.getCorrelationId() + "]");
        log.info(() -> "Routed to " + service);
        return true;
    }
}

// ─── Would be in GpLogFormatter.java ───
class GpLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
